SELECT COUNT(*) AS yoga_mat_count
FROM nlq.listings
WHERE title ILIKE '%yoga mat%' OR description ILIKE '%yoga mat%';

SELECT COUNT(*) AS deactivated_accounts
FROM nlq.students
WHERE account_status = 'deactivated';

SELECT COUNT(*) AS reviews_with_comment
FROM nlq.reviews
WHERE comment IS NOT NULL AND trim(comment) <> '';

select count(*) as no_reply_conversations
from nlq.conversations
where first_seller_reply_at is null;

SELECT COUNT(*) AS removed_listings
FROM nlq.listings_all
WHERE status = 'removed';

SELECT COUNT(*) AS listings_without_photos
FROM nlq.listings_all
WHERE photo_count IS NULL OR photo_count = 0;
